#!/usr/bin/env python3\n\"\"\"\nDigital Clock Demo - Standalone Application\nDisplays current time in multiple time zones with real-time updates\n\"\"\"\n\nimport os\nimport sys\nimport time\nfrom datetime import datetime\nimport pytz\nfrom typing import List, Dict\n\n# Add parent directory to path\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom src.digital_clock import DigitalClock, TimeFormat\n\n\nclass DigitalClockApp:\n    \"\"\"\n    Interactive Digital Clock Application\n    Displays real-time updates for multiple time zones\n    \"\"\"\n    \n    def __init__(self):\n        self.clock = DigitalClock()\n        self.running = True\n        self.refresh_interval = 1  # Update every 1 second\n        \n        # Add more time zones for demo\n        self.clock.add_timezone('America/New_York', 'New York (EST)', '🗽')\n        self.clock.add_timezone('Europe/London', 'London (GMT)', '🇬🇧')\n        self.clock.add_timezone('Asia/Tokyo', 'Tokyo (JST)', '🇯🇵')\n        self.clock.add_timezone('Australia/Sydney', 'Sydney (AEST)', '🦘')\n        self.clock.add_timezone('Asia/Dubai', 'Dubai (GST)', '🇦🇪')\n    \n    def clear_screen(self):\n        \"\"\"Clear console screen\"\"\"\n        os.system('cls' if os.name == 'nt' else 'clear')\n    \n    def display_header(self):\n        \"\"\"Display application header\"\"\"\n        print(\"\\n\" + \"=\"*80)\n        print(\"\\t\\t⏰ DIGITAL CLOCK - MULTI-TIMEZONE DISPLAY ⏰\")\n        print(\"=\"*80)\n        print(f\"Updated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\")\n        print(\"-\"*80 + \"\\n\")\n    \n    def display_all_clocks_realtime(self):\n        \"\"\"Display all clocks in real-time format\"\"\"\n        self.clear_screen()\n        self.display_header()\n        \n        # Display each timezone\n        for zone_name, tz_info in sorted(self.clock.timezones.items(), \n                                         key=lambda x: x[1].get_offset()):\n            current_time = tz_info.get_current_time()\n            time_str = tz_info.get_time_string(self.clock.time_format)\n            date_str = tz_info.get_date_string()\n            offset = tz_info.get_offset()\n            \n            # Check if business hours\n            hour = current_time.hour\n            if 9 <= hour < 17:\n                business = \"💼 WORKING\"\n            else:\n                business = \"😴 OFF-HOURS\"\n            \n            print(f\"{tz_info.emoji} {tz_info.display_name:25} | {time_str:12} | {offset:6} | {business}\")\n        \n        print(\"\\n\" + \"-\"*80)\n    \n    def display_business_hours_view(self):\n        \"\"\"Display business hours status for all zones\"\"\"\n        self.clear_screen()\n        print(\"\\n\" + \"=\"*80)\n        print(\"\\t\\t💼 BUSINESS HOURS STATUS (9 AM - 5 PM) 💼\")\n        print(\"=\"*80 + \"\\n\")\n        \n        status = self.clock.get_business_hours_status()\n        for zone_name, status_text in status.items():\n            print(f\"  {status_text}\")\n        \n        print(\"\\n\" + \"=\"*80)\n    \n    def display_timezone_comparison(self):\n        \"\"\"Display comparison between specific timezones\"\"\"\n        self.clear_screen()\n        print(\"\\n\" + \"=\"*80)\n        print(\"\\t\\t🌍 TIMEZONE COMPARISON 🌍\")\n        print(\"=\"*80 + \"\\n\")\n        \n        zones = list(self.clock.timezones.keys())\n        if len(zones) >= 2:\n            tz1, tz2 = zones[0], zones[1]\n            diff = self.clock.get_time_difference(tz1, tz2)\n            print(f\"  {diff}\\n\")\n        \n        print(\"-\"*80)\n    \n    def display_detailed_timezone(self, zone_name: str):\n        \"\"\"Display detailed information for a specific timezone\"\"\"\n        self.clear_screen()\n        print(self.clock.display_detailed_clock(zone_name))\n    \n    def run_realtime_mode(self, duration: int = 60):\n        \"\"\"\n        Run clock in real-time mode with continuous updates\n        \n        Args:\n            duration: How long to run in seconds (0 = infinite)\n        \"\"\"\n        start_time = time.time()\n        update_count = 0\n        \n        print(\"\\n⏰ Starting real-time clock display...\")\n        print(f\"   Updates every {self.refresh_interval} second(s)\")\n        if duration > 0:\n            print(f\"   Duration: {duration} seconds\")\n        print(\"   Press Ctrl+C to stop\\n\")\n        time.sleep(2)\n        \n        try:\n            while True:\n                # Check duration\n                if duration > 0 and (time.time() - start_time) > duration:\n                    break\n                \n                # Display clocks\n                self.display_all_clocks_realtime()\n                \n                # Display menu\n                print(\"\\nOptions: [1] Business Hours  [2] Compare Zones  [3] Quit\")\n                print(\"Updating in 1 second...\\n\")\n                \n                time.sleep(self.refresh_interval)\n                update_count += 1\n        \n        except KeyboardInterrupt:\n            print(\"\\n\\n✋ Stopped by user\")\n        \n        print(f\"\\nUpdates displayed: {update_count}\")\n        print(\"Exiting real-time mode...\")\n    \n    def interactive_menu(self):\n        \"\"\"Interactive menu for clock operations\"\"\"\n        while self.running:\n            self.clear_screen()\n            print(\"\\n\" + \"=\"*80)\n            print(\"\\t\\t🕐 DIGITAL CLOCK APPLICATION 🕐\")\n            print(\"=\"*80)\n            print(\"\\nMain Menu:\")\n            print(\"  [1] View All Time Zones (Real-time)\")\n            print(\"  [2] View Business Hours Status\")\n            print(\"  [3] Compare Two Time Zones\")\n            print(\"  [4] View Specific Time Zone\")\n            print(\"  [5] Switch Time Format (12h/24h)\")\n            print(\"  [6] Add Custom Time Zone\")\n            print(\"  [7] View Statistics\")\n            print(\"  [0] Exit\")\n            print(\"\\n\" + \"-\"*80)\n            \n            choice = input(\"\\nSelect option [0-7]: \").strip()\n            \n            if choice == '1':\n                self.run_realtime_mode(duration=30)\n            \n            elif choice == '2':\n                self.display_business_hours_view()\n                input(\"\\nPress Enter to continue...\")\n            \n            elif choice == '3':\n                self.display_timezone_comparison()\n                input(\"\\nPress Enter to continue...\")\n            \n            elif choice == '4':\n                self.clear_screen()\n                zones = list(self.clock.timezones.keys())\n                print(\"\\nAvailable Time Zones:\")\n                for i, zone in enumerate(zones, 1):\n                    tz_info = self.clock.get_timezone(zone)\n                    print(f\"  [{i}] {tz_info.display_name}\")\n                \n                try:\n                    zone_idx = int(input(\"\\nSelect zone number: \")) - 1\n                    if 0 <= zone_idx < len(zones):\n                        self.display_detailed_timezone(zones[zone_idx])\n                        input(\"\\nPress Enter to continue...\")\n                except ValueError:\n                    print(\"Invalid input\")\n                    time.sleep(1)\n            \n            elif choice == '5':\n                self.clear_screen()\n                current = self.clock.time_format.value\n                print(f\"\\nCurrent format: {current}\")\n                new_format = input(\"Switch to [12h/24h]? \").strip().lower()\n                \n                if new_format == '24h':\n                    self.clock.set_time_format(TimeFormat.TWENTY_FOUR_HOUR)\n                    print(\"✅ Switched to 24-hour format\")\n                elif new_format == '12h':\n                    self.clock.set_time_format(TimeFormat.TWELVE_HOUR)\n                    print(\"✅ Switched to 12-hour format\")\n                else:\n                    print(\"❌ Invalid format\")\n                \n                time.sleep(1.5)\n            \n            elif choice == '6':\n                self.clear_screen()\n                print(\"\\nAvailable zones to add:\")\n                for code, (zone_name, emoji, display_name) in self.clock.POPULAR_ZONES.items():\n                    if zone_name not in [tz.zone_name for tz in self.clock.timezones.values()]:\n                        print(f\"  {emoji} {code}: {display_name}\")\n                \n                zone_code = input(\"\\nEnter zone code (e.g., CST): \").strip().upper()\n                if self.clock.add_popular_zones([zone_code]):\n                    print(f\"✅ Added {zone_code}\")\n                else:\n                    print(f\"❌ Could not add {zone_code}\")\n                \n                time.sleep(1.5)\n            \n            elif choice == '7':\n                self.clear_screen()\n                print(\"\\n\" + \"=\"*80)\n                print(\"\\t\\t📊 CLOCK STATISTICS 📊\")\n                print(\"=\"*80)\n                print(f\"\\nTotal Time Zones: {self.clock.get_timezone_count()}\")\n                print(f\"Time Format: {self.clock.time_format.value}\")\n                print(f\"Available Zones: {', '.join(self.clock.get_available_timezones())}\")\n                print(\"\\n\" + \"=\"*80)\n                input(\"\\nPress Enter to continue...\")\n            \n            elif choice == '0':\n                self.running = False\n                print(\"\\n👋 Goodbye!\\n\")\n            \n            else:\n                print(\"❌ Invalid option. Please try again.\")\n                time.sleep(1)\n    \n    def run_demo_mode(self):\n        \"\"\"\n        Run automatic demo showing all features\n        \"\"\"\n        print(\"\\n\" + \"=\"*80)\n        print(\"\\t\\t🎬 DIGITAL CLOCK DEMO MODE 🎬\")\n        print(\"=\"*80 + \"\\n\")\n        \n        # Demo 1: Show all clocks\n        print(\"📍 Demo 1: Display all time zones\\n\")\n        print(self.clock.display_all_clocks())\n        time.sleep(3)\n        \n        # Demo 2: Show business hours\n        print(\"📍 Demo 2: Business hours status\\n\")\n        print(self.clock.display_business_hours())\n        time.sleep(3)\n        \n        # Demo 3: Show timezone details\n        print(\"📍 Demo 3: Detailed timezone info\\n\")\n        first_zone = list(self.clock.timezones.keys())[0]\n        print(self.clock.display_detailed_clock(first_zone))\n        time.sleep(3)\n        \n        # Demo 4: Switch format\n        print(\"📍 Demo 4: Switching to 24-hour format\\n\")\n        self.clock.set_time_format(TimeFormat.TWENTY_FOUR_HOUR)\n        print(self.clock.display_all_clocks())\n        time.sleep(3)\n        \n        # Demo 5: Time difference\n        print(\"📍 Demo 5: Time differences\\n\")\n        zones = list(self.clock.timezones.keys())\n        if len(zones) >= 2:\n            diff = self.clock.get_time_difference(zones[0], zones[1])\n            print(f\"  {diff}\\n\")\n        \n        print(\"\\n\" + \"=\"*80)\n        print(\"✅ Demo completed!\")\n        print(\"=\"*80 + \"\\n\")\n\n\ndef main():\n    \"\"\"\n    Main entry point\n    \"\"\"\n    print(\"\\n\" + \"=\"*80)\n    print(\"\\t\\t⏰ DIGITAL CLOCK APPLICATION ⏰\")\n    print(\"=\"*80)\n    print(\"\\nStartup Options:\")\n    print(\"  [1] Interactive Menu\")\n    print(\"  [2] Real-time Clock Display\")\n    print(\"  [3] Demo Mode\")\n    print(\"\\n\" + \"-\"*80)\n    \n    choice = input(\"\\nSelect mode [1-3]: \").strip()\n    \n    app = DigitalClockApp()\n    \n    if choice == '1':\n        app.interactive_menu()\n    elif choice == '2':\n        app.run_realtime_mode(duration=0)  # Run indefinitely\n    elif choice == '3':\n        app.run_demo_mode()\n    else:\n        print(\"\\n❌ Invalid option\")\n        time.sleep(1)\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except KeyboardInterrupt:\n        print(\"\\n\\n👋 Application stopped by user\")\n    except Exception as e:\n        print(f\"\\n❌ Error: {e}\")\n        import traceback\n        traceback.print_exc()\n"